    content = file.read()
    amounts = []
    for line in content.split('\n'):
        if '$' in line:
            amount = ''.join(filter(str.isdigit, line.split('$')[-1])).replace(',', '')
            if amount:
                amounts.append(int(amount))
    print(amounts)

